public class ProfilingLauncher {
    // Production JVM flags to enable remote JMX and Flight Recorder without heavy instrumentation overhead
    // -XX:+UnlockCommercialFeatures -XX:+FlightRecorder 
    // -Dcom.sun.management.jmxremote -Dcom.sun.management.jmxremote.port=9010 
    // -Dcom.sun.management.jmxremote.authenticate=false -Dcom.sun.management.jmxremote.ssl=false
    public static void main(String[] args) {
        System.out.println("Application started for profiling diagnostics...");
        while (true) {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }
}
